css:
@keyframes crtFlicker {
0%, 100% { opacity: 0.97; }
50% { opacity: 1; }
}
@keyframes crtRoll {
from { background-position: 0 -30vh, 0 0, 0 0; }
to { background-position: 0 130vh, 0 0, 0 0; }
}

.dark ::-webkit-scrollbar {
width: 8px;
height: 8px;
}
.dark ::-webkit-scrollbar-track {
background: #000000;
}
.dark ::-webkit-scrollbar-thumb {
background: #00b82e;
border-radius: 0;
}
.dark [data-slot="scroll-area-thumb"] {
background: #00b82e !important;
}
.dark svg.lucide {
stroke-linecap: square !important;
stroke-linejoin: miter !important;
}
.dark ::selection {
background: #00ff41;
color: #000000;
text-shadow: none;
}

.dark body,
.dark body * {
font-family: "Cascadia Mono", Consolas, "Lucida Console", "MS Gothic", monospace !important;
letter-spacing: 0;
-webkit-font-smoothing: antialiased;
}
.dark body {
background: #000000 !important;
text-shadow: 0 0 2px rgba(0, 255, 65, 0.3), 0 0 7px rgba(0, 255, 65, 0.14);
}

/* The glass: scanlines, rolling refresh band, vignette, over everything */
.dark body::after {
content: "";
position: fixed;
inset: 0;
z-index: 2147483647;
pointer-events: none;
background-image:
    linear-gradient(180deg, transparent, rgba(0, 255, 65, 0.045) 50%, transparent),
    repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.18) 0, rgba(0, 0, 0, 0.18) 1px, transparent 1px, transparent 3px),
    radial-gradient(ellipse 120% 100% at 50% 50%, transparent 70%, rgba(0, 0, 0, 0.55) 100%);
background-size: 100% 18vh, 100% 100%, 100% 100%;
background-repeat: no-repeat, repeat, no-repeat;
animation: crtRoll 9s linear infinite, crtFlicker 0.3s steps(2) infinite;
}

.dark .chat-markdown,
.dark .chat-markdown *:not(code) {
color: #58e883 !important;
}
.dark .chat-markdown h1,
.dark .chat-markdown h2,
.dark .chat-markdown h3 {
color: #9ee8b3 !important;
text-transform: uppercase;
text-shadow: 0 0 4px rgba(0, 255, 65, 0.45), 0 0 12px rgba(0, 255, 65, 0.25);
}
.dark .chat-markdown h1::before,
.dark .chat-markdown h2::before,
.dark .chat-markdown h3::before {
content: "> ";
color: #00ff41;
}
.dark .chat-markdown a {
color: #9ee8b3 !important;
text-decoration: underline dashed !important;
}
.dark .chat-markdown :not(pre) > code {
color: #000000 !important;
background: #00ff41 !important;
text-shadow: none !important;
border-radius: 0 !important;
}
.dark .chat-markdown li::marker {
color: #00ff41;
content: "* ";
}

/* Sidebar: plain phosphor directory listing */
.dark [data-slot="sidebar-inner"] {
background: #000000 !important;
border-right: 1px solid #0d5c22 !important;
}
.dark [data-thread-item] {
border-radius: 0 !important;
border: 1px solid transparent !important;
}
.dark [data-thread-item]:hover {
background: #002a0d !important;
border-color: #00ff41 !important;
}
.dark [data-thread-item]:hover * {
color: #eafff0 !important;
}
.dark [data-thread-item][data-active="true"],
.dark [data-thread-item][aria-current="page"] {
background: #004d1a !important;
border-color: #00ff41 !important;
box-shadow: inset 3px 0 0 #00ff41 !important;
}
.dark [data-thread-item][data-active="true"] *,
.dark [data-thread-item][aria-current="page"] * {
color: #ffffff !important;
}
.dark [data-slot="project-monogram"] {
border-radius: 0 !important;
filter: grayscale(1) sepia(1) hue-rotate(70deg) saturate(6);
}

.dark [data-chat-header] {
background: #000000 !important;
border-bottom: 1px dashed #00b82e !important;
}

/* User bubble: a typed command line */
.dark [data-user-message-bubble] {
background: #000a02 !important;
border: 1px solid #00b82e !important;
border-radius: 0 !important;
color: #9ee8b3 !important;
box-shadow: 0 0 10px rgba(0, 255, 65, 0.22) !important;
}
.dark [data-user-message-bubble]::before {
content: "neo@nebuchadnezzar:~$ ";
color: #00ff41;
opacity: 0.75;
}

.dark .chat-markdown-codeblock {
background: #000000 !important;
border: 1px solid #0d5c22 !important;
border-radius: 0 !important;
box-shadow: inset 0 0 30px rgba(0, 255, 65, 0.08) !important;
}

.dark [data-slot="composer-host"] {
background: #000000 !important;
border: 1px solid #00b82e !important;
border-radius: 0 !important;
box-shadow: 0 0 12px rgba(0, 255, 65, 0.15) !important;
}
.dark [data-slot="composer-host"]:focus-within {
border-color: #00ff41 !important;
box-shadow: 0 0 18px rgba(0, 255, 65, 0.35), inset 0 0 14px rgba(0, 255, 65, 0.08) !important;
}
.dark .composer-tiptap {
caret-color: #00ff41;
color: #9ee8b3 !important;
}

.dark [data-slot="button"],
.dark [data-slot="input"],
.dark [data-slot="select-trigger"],
.dark [data-slot="dialog-popup"],
.dark [data-slot="popover-popup"],
.dark [data-slot="menu-popup"],
.dark [data-slot="tooltip-popup"],
.dark [data-thread-details-card] {
border-radius: 0 !important;
}
.dark [data-slot="button"]:hover {
background: #003d14 !important;
color: #eafff0 !important;
box-shadow: inset 0 0 0 1px #00ff41 !important;
}
.dark [data-slot="button"]:hover * {
color: #eafff0 !important;
}
.dark [data-slot="dialog-popup"],
.dark [data-slot="popover-popup"],
.dark [data-slot="menu-popup"],
.dark [data-thread-details-card] {
background: #000000 !important;
border: 1px solid #00b82e !important;
box-shadow: 0 0 20px rgba(0, 255, 65, 0.2) !important;
}
.dark [data-slot="tooltip-popup"] {
background: #001a08 !important;
border: 1px solid #00ff41 !important;
color: #eafff0 !important;
}
.dark [data-thread-terminal-drawer] {
border-top: 1px dashed #00ff41 !important;
}
@media (prefers-reduced-motion: reduce) {
.dark body::after {
    animation: none !important;
}
}

/* Menu and list hovers: dark fill, bright text */
.dark [role="menuitem"]:hover,
.dark [role="menuitem"][data-highlighted],
.dark [role="option"][data-highlighted],
.dark [role="option"]:hover {
background: #003d14 !important;
color: #eafff0 !important;
}

